import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        int[] sl = new int[52];
        sl[0] = 1;
        for (int i = 1; i <= 51; i++) {
            sl[i] = sl[i - 1] + (1 << i);
        }

        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int n = scanner.nextInt();

        List<Integer> nl = new ArrayList<>();
        n += sl[h - 1];
        int tn = n;
        nl.add(tn);
        while (tn != 1) {
            tn = tn / 2;
            nl.add(tn);
        }

        int ans = 0;
        int cn = 1;
        boolean cp = false;

        while (cn != n) {
            List<Integer> tnl = new ArrayList<>();
            int tempCn = cn;
            for (int i = 0; i < h; i++) {
                tnl.add(tempCn);
                if (!cp) {
                    tempCn = tempCn * 2;
                } else {
                    tempCn = tempCn * 2 + 1;
                }
                cp = !cp;
            }
            if (tempCn == n) {
                ans += h;
                break;
            }
            tnl.add(tempCn);
            // reverse tnl
            for (int i = 0; i < tnl.size() / 2; i++) {
                int tmp = tnl.get(i);
                tnl.set(i, tnl.get(tnl.size() - 1 - i));
                tnl.set(tnl.size() - 1 - i, tmp);
            }
            for (int i = 1; i <= h; i++) {
                if (sl[i - 1] == tnl.get(i)) {
                    ans += sl[i - 1] + h - i + 1;
                    h = i - 1;
                    cn = tnl.get(i - 1);
                    if (cn == tnl.get(i) * 2) {
                        cn = tnl.get(i) * 2 + 1;
                        cp = false;
                    } else {
                        cn = tnl.get(i) * 2;
                        cp = true;
                    }
                    break;
                }
            }
        }
        System.out.println(ans);
        scanner.close();
    }
}
